 * @param props see ZimmDrawerContentConfig
 */
const ZimmDrawerContent = ({
  children,
  onClose,
  title,
  titleId,
  titleStyle = 'large',
  labelledBy,
  ariaLabel,
  boxedHeader,
  contentStyles,
  headerStyles,
  headerTitleStyles,
  closeButtonStyles,
  headerCloseButtonStyles,
