import React from 'react';
import { describe, test, expect, vi, beforeEach, afterEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import theme from 'app/theme';
import { ZimmDrawer } from './index';
import { useUiCopy } from 'app/hooks/useUiCopy';

// First index.test.tsx for this component (SFCC-831) — zimmDrawer.css.test.ts already covers the
// recipe; this file is scoped to the `boxedHeader` capability being introduced here, plus the
// minimum regression coverage needed to prove the two pre-existing header paths (`title` and
// `labelledBy` alone) still behave exactly as before. It is deliberately not a comprehensive suite
// for every existing prop (sizes, titleStyle, finalFocusRef/initialFocusRef, etc.).

// ZimmIcon throws under Vitest (base SFCC icons barrel side-effect issue — see testing.md's
// "Known gap: ZimmIcon throws under Vitest"). ZimmButton's icon variant, rendered for every one of
// ZimmDrawer's own close buttons, imports it at module scope, so every test below needs this
// mocked regardless of scenario.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({ ZimmIcon: () => null }));

// Same technique zimmCountryLanguageMismatch/index.test.tsx uses for the same hook — isolates this
// suite from UiCopyProvider's own fetch/lookup logic (covered by its own test coverage) and gives
// the close button a fixed, assertable accessible name. Not load-bearing for correctness here —
// useUiCopy degrades to the literal fallback ('Close') with no Provider mounted at all (see
// useUiCopy.ts) — but kept for consistency with the established pattern elsewhere in this codebase.
vi.mock('app/hooks/useUiCopy', () => ({ useUiCopy: vi.fn() }));

const mockUseUiCopy = vi.mocked(useUiCopy);
const mockT = vi.fn((_key: string, fallback: string) => fallback);

const renderDrawer = (ui: React.ReactElement) => render(<ChakraProvider theme={theme}>{ui}</ChakraProvider>);

describe('ZimmDrawer', () => {
  beforeEach(() => {
    mockT.mockImplementation((_key: string, fallback: string) => fallback);
    mockUseUiCopy.mockReturnValue({ t: mockT, isLoading: false });
  });

  afterEach(() => {
    vi.clearAllMocks();
  });

  describe('title (regression check — pre-existing path)', () => {
    test('renders the in-flow header box; the dialog is named from the title text', () => {
      renderDrawer(
        <ZimmDrawer isOpen onClose={vi.fn()} size="large" title="SIGN IN">
          <p>Body content</p>
        </ZimmDrawer>,
      );

      const dialog = screen.getByRole('dialog', { name: 'SIGN IN' });
      expect(dialog).toBeInTheDocument();

      const closeButton = screen.getByRole('button', { name: 'Close' });
      expect(closeButton).toBeInTheDocument();

      // Same structural landmark used for the new boxedHeader case below: a title <span> then the
      // close button's own row, sharing one in-flow header box — not the close button alone. One
      // level deeper than before the SFCC-831/689 rework: the boxed close button is now wrapped
      // in its own `headerCloseButton` part (a real 44px row — see zimmDrawer.css.ts), so this
      // walks through that wrapper to reach the shared header box.
      const headerBox = closeButton.parentElement?.parentElement;
      expect(headerBox?.children).toHaveLength(2);
      expect(headerBox?.children[0].tagName).toBe('SPAN');
      expect(headerBox?.children[0]).toHaveTextContent('SIGN IN');
      // The header part carries no `position` override in zimmDrawer.css.ts (in-flow) — unlike
      // the floating closeButton part asserted in the next describe block.
      expect(headerBox).not.toHaveStyle({ position: 'absolute' });
    });
  });

  describe('labelledBy, no boxedHeader (regression check — pre-existing path)', () => {
    test('close button floats (not boxed); the dialog is named from the external labelledBy target, not any rendered header text', () => {
      renderDrawer(
        <div>
          <h2 id="ext-label">External heading</h2>
          <ZimmDrawer isOpen onClose={vi.fn()} size="small" labelledBy="ext-label">
            <p>Body content</p>
          </ZimmDrawer>
        </div>,
      );

      const dialog = screen.getByRole('dialog', { name: 'External heading' });
      expect(dialog).toBeInTheDocument();

      const closeButton = screen.getByRole('button', { name: 'Close' });
      expect(closeButton).toBeInTheDocument();

      // No title-row sibling: the floating close button's own box has exactly one child (the
      // button itself) — the boxed treatment always renders a title <span> before it (see the
      // title and boxedHeader tests), so its absence is the DOM landmark for "not boxed."
      const floatingBox = closeButton.parentElement;
      expect(floatingBox?.children).toHaveLength(1);
      // CSS proof of the same thing: zimmDrawer.css.ts's closeButton part is `position: absolute`
      // (unconditioned by any variant/breakpoint), unlike the header part above.
      expect(floatingBox).toHaveStyle({ position: 'absolute' });
    });
  });

  describe('labelledBy + boxedHeader (new path)', () => {
    test('close button renders boxed (in-flow header row, empty title span); the dialog is still named from the external labelledBy target', () => {
      renderDrawer(
        <div>
          <h2 id="ext-label-2">Another external heading</h2>
          <ZimmDrawer isOpen onClose={vi.fn()} size="prompt" labelledBy="ext-label-2" boxedHeader>
            <p>Body content</p>
          </ZimmDrawer>
        </div>,
      );

      const dialog = screen.getByRole('dialog', { name: 'Another external heading' });
      expect(dialog).toBeInTheDocument();

      const closeButton = screen.getByRole('button', { name: 'Close' });
      expect(closeButton).toBeInTheDocument();

      // Structural (DOM-landmark) proof of "boxed, not floating": the same header box the `title`
      // case renders above — an empty title <span> occupying the header's flex-1 slot, immediately
      // followed by a close-button row — rather than the close button alone (the previous describe
      // block's floatingBox). This is the mechanical signal jsdom can actually observe. One level
      // deeper than before the SFCC-831/689 rework — see the `title` case above for why.
      const headerBox = closeButton.parentElement?.parentElement;
      expect(headerBox?.children).toHaveLength(2);
      expect(headerBox?.children[0].tagName).toBe('SPAN');
      expect(headerBox?.children[0]).toHaveTextContent('');
      // No id on the empty span — only the `title` case labels via id (see index.tsx); the
      // dialog's accessible name must keep coming from the external labelledBy target, not this
      // span, confirmed above via the dialog's own accessible name.
      expect(headerBox?.children[0]).not.toHaveAttribute('id');
      // children[1] is now the close button's own wrapper row (`headerCloseButton`), not the
      // button element itself — it still contains the same button.
      expect(headerBox?.children[1]).toContainElement(closeButton);

      // CSS proof of the same thing: no `position: absolute` override here, matching the `title`
      // case's header box and unlike the previous describe block's floating close button.
      //
      // What this test cannot prove: jsdom has no layout engine, so none of the above shows the
      // close button actually lands in the same real on-screen position `title`'s header produces,
      // only that the same recipe part (and therefore the same declared CSS, including the
      // non-absolute position) is applied. Genuine visual placement still needs a real browser —
      // Storybook or a manual check — not this test.
      expect(headerBox).not.toHaveStyle({ position: 'absolute' });
    });
  });
});

import { createContext, useContext } from 'react';

export type UiCopyContextValue = {
  /**
   * Returns the CMS value for `key`, or `fallback` while the fetch is loading, on fetch
   * error, or when no `uiCopy` entry with that key exists yet. When `values` is passed,
   * every `{token}` in the resolved string (CMS value or fallback) is replaced from it —
   * mirrors react-intl's `formatMessage(descriptor, values)` shape closely enough that a
   * call site converting away from react-intl only has to change the function, not the
   * string template itself.
   */
  t: (key: string, fallback: string, values?: Record<string, string | number>) => string;
  isLoading: boolean;
};

/**
 * Replaces every `{token}` in `template` with `values[token]`, left untouched if `token`
 * isn't in `values`. Shared by both the real UiCopyProvider and FALLBACK_ONLY below so a
 * key with no matching Contentful entry still interpolates correctly against its fallback.
 */
export const interpolateUiCopy = (template: string, values?: Record<string, string | number>): string => {
  if (!values) return template;
  return template.replace(/\{(\w+)\}/g, (match, token: string) => (token in values ? String(values[token]) : match));
};

/**
 * Populated by UiCopyProvider (overrides/app/components/uiCopyProvider), mounted once in
 * _app-config. Not meant to be consumed directly — call useUiCopy() instead, which supplies
 * the no-Provider fallback.
 */
export const UiCopyContext = createContext<UiCopyContextValue | undefined>(undefined);

const FALLBACK_ONLY: UiCopyContextValue = {
  t: (_key: string, fallback: string, values?: Record<string, string | number>) => interpolateUiCopy(fallback, values),
  isLoading: false,
};

/**
 * App-wide UI-copy lookup, backed by Contentful's uiCopy content type — one entry per string,
 * fetched in a single bulk call by UiCopyProvider and shared via context, the same pattern
 * this app already uses for translations (`useIntl`) rather than the per-page container-fetch
 * pattern commerce-sdk-react hooks use. uiCopy is app-wide static content, not page-specific
 * business data, so it's safe to call from any component — including presentational leaves —
 * without threading it through as a prop.
 *
 * Safe to call with no UiCopyProvider mounted above it (Storybook, an isolated unit test):
 * degrades to fallback-only text instead of throwing, so every call site stays functional and
 * testable with zero setup.
 *
 * @returns `t` lookup function plus `isLoading`
 */
export const useUiCopy = (): UiCopyContextValue => useContext(UiCopyContext) ?? FALLBACK_ONLY;

